import assert from 'node:assert/strict';import {writeFileSync,readFileSync,chmodSync,readdirSync,existsSync} from 'node:fs';import {join,resolve} from 'node:path';import {createHash} from 'node:crypto';
import {makeRepo,CHANGE} from './helpers.mjs';import {runRun} from '../../../packages/runner/dist/index.js';import {withProcessBudget} from '../../../packages/kit/dist/process.js';
const repo=makeRepo();const start=performance.now();let result;
try{
 const marker=join(repo.base,'slow-hook-start'),done=join(repo.base,'slow-hook-end');
 const hook=join(repo.root,'.git/hooks/pre-commit');
 const code=`const fs=require('node:fs');fs.writeFileSync(${JSON.stringify(marker)},String(Date.now()));setTimeout(()=>fs.writeFileSync(${JSON.stringify(done)},String(Date.now())),40000)`;
 const quoted="'"+code.replaceAll("'","'\\''")+"'";
 writeFileSync(hook,`#!/bin/sh\nif [ ! -e '${marker}' ]; then\n  '${process.execPath}' -e ${quoted}\nfi\n`);chmodSync(hook,0o755);
 repo.plan([{write:{'impl.txt':'implementation\n'}},{}]);const out=[];
 const status=await withProcessBudget({timeoutMs:90000,maxOperationMs:30000},()=>runRun({root:repo.root,changeId:CHANGE,interactive:false,confirm:async()=>false,stdout:t=>out.push(t),env:repo.env,fileExists:()=>false}));
 assert.equal(status,0,out.join('\n'));assert(existsSync(done));const hookMs=Number(readFileSync(done,'utf8'))-Number(readFileSync(marker,'utf8'));assert(hookMs>=40000);
 const runs=join(repo.root,'.loomake/runs');const run=readdirSync(runs).filter(x=>x!=='.gitignore').sort().at(-1);const summary=JSON.parse(readFileSync(join(runs,run,'summary.json'),'utf8'));assert.equal(summary.status,'completed');assert.deepEqual(summary.remainingTasks,[]);assert.equal(repo.prs().length,1);
 result={status:'passed',sourceCommit:'6312137',platform:process.platform,arch:process.arch,node:process.version,operationLimitMs:30000,sharedBudgetMs:90000,hookElapsedMs:hookMs,totalElapsedMs:performance.now()-start,runExitCode:status,summaryStatus:summary.status,remainingTasks:summary.remainingTasks,prs:repo.prs().length,scope:'Compiled local runner, real Git and a one-time 40-second pre-commit hook; fake engine and fake gh; Linux only',probeSha256:createHash('sha256').update(readFileSync(new URL(import.meta.url))).digest('hex')};
}catch(error){result={status:'failed',error:String(error),elapsedMs:performance.now()-start};process.exitCode=1;}finally{repo.cleanup();}
writeFileSync(resolve('.loomake/quality/edge-probes/slow-hook-results.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
